export function sum(arr: number[]) {
  return arr.reduce((acc, curr) => acc + curr, 0)
}

export function sum(arr: number[]): number {
  return arr.reduce((acc, cur) => acc + cur, 0);
}

export function sum(array: number[]): number {
  return array.reduce((acc, value) => acc + value, 0)
}

function runtimeTotal(movies: FranchiseMovie[]): number {
  return movies.reduce((sum, movie) => sum + (movie.runtime || 0), 0);
}

export function totalFree(blocks: MemoryBlock[]): number {
  return blocks.filter((b) => b.pid === -1).reduce((s, b) => s + b.size, 0);
}

export function totalSpent(entries: Entry[]): number {
  return entries
    .filter((e) => e.kind === "expense")
    .reduce((sum, e) => sum + e.amount_cents, 0);
}

export function hasError(results: ESLintNamespace.LintResult[]): boolean {
  return results.some((result) => result.errorCount > 0);
}

export function stripTwapZeros(chain: number[]): number[] {
  return chain.filter((component) => component > 0);
}

function capturedMaximum(values: readonly number[]): number {
  return values.length === 0 ? 0 : Math.max(...values);
}

function capturedMinimum(values: readonly number[]): number {
  return values.length === 0 ? 0 : Math.min(...values);
}

export function max(xs: number[]): number {
  return xs.length === 0 ? 0 : Math.max(...xs);
}

export function maxNumber(values: number[]): number {
  return values.reduce((max, value) => Math.max(max, value), 0);
}

export function max(numbers: number[]): number {
  return numbers.reduce((prev, cur) => Math.max(prev, cur), 0);
}

export function filterFinite(arr: number[]): number[] {
  return arr.filter(isFinite);
}

export function hasInvalidNumber(values: number[]): boolean {
  return values.some((value) => !Number.isFinite(value));
}

export function compact(xs: readonly (number | null)[]): number[] {
  return xs.filter((x): x is number => x !== null && Number.isFinite(x));
}

export function calcActiveSum(subs: Subscription[]): number {
  return subs
    .filter((s) => s.isActive)
    .reduce((sum, s) => sum + (Number.isFinite(s.currentCredits) ? s.currentCredits : 0), 0);
}
